using System.Collections.ObjectModel; using CommunityToolkit.Mvvm.ComponentModel; using CommunityToolkit.Mvvm.Input; using DarouichTravaux.Application; using DarouichTravaux.Domain;
namespace DarouichTravaux.Maui.ViewModels; public partial class ClientsViewModel(IClientService service):ObservableObject { public ObservableCollection<Client> Clients{get;}=[];[ObservableProperty]private string search="";[RelayCommand]public async Task LoadAsync(){Clients.Clear();foreach(var client in await service.SearchAsync(Search))Clients.Add(client);}[RelayCommand]private async Task AddAsync(){await service.SaveAsync(new Client{Name="Nouveau client"});await LoadAsync();} }
